<script setup lang="ts">
/**
 * A joined row of segments that always holds one value (`design/components/segmented-control.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/segmented-control.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, inject, onBeforeUnmount, onMounted, provide, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/radio-group'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, roveRadio, useDirection, type IconRole } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/segmented-control.module.css'

export type SegmentedControlSize = NonNullable<SegmentedControlProps['size']>

export interface SegmentedControlOption {
  value: string
  label: string
  icon?: IconRole
  disabled?: boolean
}

export interface SegmentedControlProps {
  defaultValue?: string
  /**
   * Disables the whole group. Use `disabled` in `options` for single options.
   */
  disabled?: boolean
  /**
   * The group's accessible name, because outside a form there is no FormField to name it.
   */
  label: string
  /**
   * Items render from data, because free-form children invite ad hoc layouts (Radio's law).
   */
  options: SegmentedControlOption[]
  /**
   * There is no `lg`, on purpose. A segmented control is an inline control used in toolbars,
   * page headers and filter rows next to `sm`/`md` controls. A form-sized single choice is
   * RadioGroup in a FormField, not this at 44px.
   */
  size?: 'sm' | 'md'
  value?: string
}

defineOptions({ name: 'SegmentedControl', inheritAttrs: false })

const props = withDefaults(defineProps<SegmentedControlProps>(), { disabled: false, size: 'md' })
const emit = defineEmits<{ change: [value: string] }>()
const uid = useId()
const lent = inject<string | undefined>('polymorph:identity', undefined)
const lender = inject<{ element?: () => Element | null | undefined } | undefined>(
  'polymorph:borrowed',
  undefined,
)
provide('polymorph:borrowed', undefined)
const track = useTemplateRef<HTMLElement>('track')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    value: props.value,
    defaultValue: props.defaultValue ?? props.options[0]?.value,
    disabled: props.disabled,
    onValueChange: (details) => {
      emit('change', details.value ?? '')
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const stop = computed(
  () =>
    api.value.value ??
    props.options.find((option) => !(props.disabled || option.disabled === true))?.value,
)
const effect1 = () => {
  lender && (lender.element = () => track.value)
}
onMounted(effect1)
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'SegmentedControl',
    element: () => track.value,
    state: () => ({
      value: api.value.value ?? null,
      options: props.options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      disabled: props.disabled,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => value !== api.value.value && api.value.setValue(value),
      },
    },
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <div
    ref="track"
    :class="styles.track"
    role="radiogroup"
    :aria-label="label"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-member="lent ?? 'segmented-control'"
  >
    <template v-for="option in options" :key="option.value">
      <!-- segment -->
      <button
        :class="styles.segment"
        type="button"
        role="radio"
        :value="option.value"
        :aria-checked="api.value === option.value"
        :disabled="disabled || option.disabled === true"
        :tabindex="option.value === stop ? 0 : -1"
        :data-state="api.value === option.value ? 'checked' : 'unchecked'"
        :data-disabled="disabled || option.disabled === true ? '' : undefined"
        @click="api.setValue(option.value)"
        @keydown="
          $event.key === 'Enter'
            ? $event.preventDefault()
            : roveRadio($event, (next) => api.setValue(next))
        "
      >
        <span v-if="api.value === option.value" :class="styles.chip" data-state="checked" />
        <span v-if="option.icon !== undefined" :class="styles.glyph">
          <Icon :name="option.icon" :size="size" />
        </span>
        <span :class="styles.label">
          {{ option.label }}
        </span>
      </button>
    </template>
  </div>
</template>
